with valid_stores as (select * from stores where city = 'Bangkok' and sqft > 4796 and sqft = 13462), agg as (select city, case when sqft >= 13588 then 'high' when sqft >= 7860 then 'mid' else 'low' end as sqft_bucket, sort_array(collect_set(region)) as region_list from valid_stores group by city, case when sqft >= 13588 then 'high' when sqft >= 7860 then 'mid' else 'low' end) select * from agg order by city desc
